import{_ as d,I as a,c as n,o as t,a7 as r,b as c,w as o,a as i,J as l,a8 as h}from"./chunks/framework.BVGSIcOn.js";const k=JSON.parse('{"title":"Design: fetch resolve-on-response error model","description":"","frontmatter":{},"headers":[],"relativePath":"design/fetch-resolve-on-response.md","filePath":"design/fetch-resolve-on-response.md"}'),p={name:"design/fetch-resolve-on-response.md"};function u(f,e,m,g,b,x){const s=a("Mermaid");return t(),n("div",null,[e[1]||(e[1]=r('<h1 id="design-fetch-resolve-on-response-error-model" tabindex="-1">Design: fetch resolve-on-response error model <a class="header-anchor" href="#design-fetch-resolve-on-response-error-model" aria-label="Permalink to “Design: fetch resolve-on-response error model”">​</a></h1><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><p><code>FetchEngine</code> throws a <code>FetchError</code> for every non-2xx response (<code>executor.ts:715-724</code>). A 400/500 is a <em>completed</em> HTTP exchange — the server received, processed, and answered — yet the engine destroys the response and rebuilds a lossy projection of it onto an error object:</p><ul><li>Response headers are lost. <code>FetchError.headers</code> carries <strong>request</strong> headers; the documented <code>error.headers[&#39;retry-after&#39;]</code> retry pattern reads <code>undefined</code>, always.</li><li>The body is smuggled as untyped <code>err.data</code>.</li><li>The sanctioned usage pattern (<code>attempt()</code> tuples) immediately catches the throw and converts it back into a value — the library&#39;s own errors-as-values philosophy, round-tripped through exception machinery for nothing.</li><li>Five unrelated situations (cancel, timeout, connection lost, non-2xx answer, unparsable body) exit through one channel and must be disentangled by the caller.</li><li><code>afterRequest</code> hooks never see non-2xx: Set-Cookie on 401/403 is silently dropped (RFC 6265 violation), and the cache/cookie plugins are blind to half of reality.</li><li>Internal precedent already exists: <code>.raw()</code> and <code>.stream()</code> resolve on non-2xx today (no ok-check on that path, <code>executor.ts:682-688</code>).</li></ul><p>Outcome channels, new model:</p>',5)),(t(),c(h,null,{default:o(()=>[l(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20R%5Brequest%5D%20--%3E%20X%7Bexchange%20completed%3F%7D%0A%20%20%20%20X%20--%20%22no%3A%20abort%20%2F%20timeout%20%2F%5Cnconnection%20lost%20%2F%20parse-on-ok%22%20--%3E%20E%5B%22attempt()%20error%3A%20FetchError%5Cn(transport%20only)%22%5D%0A%20%20%20%20X%20--%20yes%20--%3E%20OK%7Bres.ok%3F%7D%0A%20%20%20%20OK%20--%20false%20--%3E%20N%5B%22resolves%20%7B%20ok%3A%20false%20%7D%5Cnstatus%20%C2%B7%20headers%20%C2%B7%20data%22%5D%0A%20%20%20%20OK%20--%20true%20--%3E%20Y%5B%22resolves%20%7B%20ok%3A%20true%20%7D%5Cndata%3A%20T%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r(`<h2 id="goals-non-goals" tabindex="-1">Goals / Non-goals <a class="header-anchor" href="#goals-non-goals" aria-label="Permalink to “Goals / Non-goals”">​</a></h2><p>Goals:</p><ul><li>Non-2xx responses resolve as <code>FetchResponse</code> with full <code>status</code> / <code>headers</code> / <code>data</code>.</li><li><code>FetchError</code> narrows to transport-only: abort, timeout, connection lost, parse failure on <code>ok: true</code>, client-side rate-limit reject.</li><li><code>FetchResponse</code> becomes a discriminated union on <code>ok</code> so TypeScript forces the negative-path check.</li><li>Event taxonomy recalibrated: <code>response</code> universal, <code>error</code> transport-only, new <code>response-4xx</code> / <code>response-5xx</code> diagnostics channels.</li><li>Retry decisions receive the response when one exists.</li></ul><p>Non-goals:</p><ul><li>No <code>throwHttpErrors</code> / <code>validateStatus</code> escape hatch — clean break, major version.</li><li>No caching of <code>ok: false</code> responses (HTTP-cacheable 404s may be a later opt-in).</li><li>No change to <code>.raw()</code> / <code>.stream()</code> semantics (already resolve-on-response).</li><li>No change to rate-limit plugin behavior (client-side reject stays an error — no response exists).</li><li>No redirect (3xx) or informational (1xx) dedicated events — <code>response</code> covers them.</li></ul><h2 id="approaches" tabindex="-1">Approaches <a class="header-anchor" href="#approaches" aria-label="Permalink to “Approaches”">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Approach</th><th>Pros</th><th>Cons</th></tr></thead><tbody><tr><td>A</td><td>Status quo + attach response headers to <code>FetchError</code></td><td>Smallest diff; fixes the <code>retry-after</code> symptom</td><td>Keeps the category error; error object keeps growing into a shadow response</td></tr><tr><td>B</td><td>Configurable throw (<code>validateStatus</code>, axios-style)</td><td>Per-instance choice</td><td>Two contracts to test/document forever; default still wrong</td></tr><tr><td>C</td><td>Resolve-on-response, discriminated union on <code>ok</code></td><td>Honest channels; aligns with <code>attempt()</code> philosophy and platform <code>fetch()</code>; compiler-enforced negative path; fixes cookie/cache blindness</td><td>Major breaking change; wide type/test/docs ripple</td></tr><tr><td>D</td><td>C + <code>throwHttpErrors: true</code> escape hatch (got-style)</td><td>Softer migration</td><td>Doubles permanent test/doc surface for a transitional need</td></tr></tbody></table><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><p><strong>C — clean break.</strong> The library&#39;s identity is errors-as-values; the engine should practice it. Decisions locked with the user (2026-07-08):</p><table tabindex="0"><thead><tr><th>#</th><th>Decision</th></tr></thead><tbody><tr><td>1</td><td><code>shouldRetry</code> receives <code>FetchResponse | FetchError</code> — response for HTTP-status retries, error for transport retries. <code>retryableStatusCodes</code> stays as the zero-config default.</td></tr><tr><td>2</td><td>Parse failure on an <code>ok: false</code> body falls back to raw text in <code>data</code> — the body format never masks the status. Parse failure on <code>ok: true</code> remains an error (contract broken).</td></tr><tr><td>3</td><td>Clean break. No escape hatch. Major version via changesets.</td></tr><tr><td>4</td><td>New events <code>response-4xx</code> / <code>response-5xx</code>; <code>response</code> becomes universal; <code>error</code> narrows; per-attempt emission (mirrors today&#39;s per-attempt <code>error</code>).</td></tr></tbody></table><h2 id="dx-comparison" tabindex="-1">DX comparison <a class="header-anchor" href="#dx-comparison" aria-label="Permalink to “DX comparison”">​</a></h2><p>Today — five situations, one tangled channel; the response is destroyed on non-2xx:</p><pre><code>\`\`\`ts
const [res, err] = await attempt(() =&gt; api.get&lt;User&gt;(&#39;/users/123&#39;));

if (err) {

    if (isFetchError(err)) {

        if (err.isCancelled())      return;
        if (err.isTimeout())        return retryLater();
        if (err.isConnectionLost()) return goOffline();

        if (err.status === 400) return showValidation(err.data); // untyped, smuggled
        if (err.status &gt;= 500)  return alertOps(err.requestId);  // err.headers = REQUEST headers
        if (err.step === &#39;parse&#39;) return badPayload();
    }
    return;
}

res.data;    // only 2xx reaches here
\`\`\`
</code></pre><p>New — three honest channels:</p><pre><code>\`\`\`ts
const [res, err] = await attempt(() =&gt; api.get&lt;User&gt;(&#39;/users/123&#39;));

if (err) {
    // transport only — no response exists
    if (err.isCancelled())      return;
    if (err.isTimeout())        return retryLater();
    if (err.isConnectionLost()) return goOffline();
    return badPayload(err);    // parse contract broken on a 2xx
}

if (!res.ok) {
    // exchange succeeded; the answer was &quot;no&quot; — full response available
    res.headers[&#39;retry-after&#39;];    // present
    if (res.status === 400) return showValidation(res.data);
    if (res.status &gt;= 500)  return alertOps(res.headers[&#39;x-request-id&#39;]);
    return;
}

res.data;    // narrowed to User by the ok check
\`\`\`
</code></pre><p>New <code>shouldRetry</code> shape:</p><pre><code>\`\`\`ts
shouldRetry(outcome: FetchResponse&lt;unknown&gt; | FetchError, attempt: number): boolean | number {

    if (isFetchError(outcome)) return outcome.isConnectionLost();

    if (outcome.status === 429) {
        const after = outcome.headers[&#39;retry-after&#39;];
        return after ? Number(after) * 1000 : 5000;
    }

    return outcome.status &gt;= 500;
}
\`\`\`
</code></pre><h2 id="event-taxonomy" tabindex="-1">Event taxonomy <a class="header-anchor" href="#event-taxonomy" aria-label="Permalink to “Event taxonomy”">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Today</th><th>New</th></tr></thead><tbody><tr><td><code>response</code></td><td>2xx only (emit sits after the ok-throw)</td><td>all responses, any status</td></tr><tr><td><code>error</code></td><td>non-2xx + transport + parse</td><td>transport + parse-on-ok + rate-limit reject</td></tr><tr><td><code>abort</code></td><td>cancellations/timeouts</td><td>unchanged</td></tr><tr><td><code>response-4xx</code></td><td>—</td><td>new: client-error diagnostics</td></tr><tr><td><code>response-5xx</code></td><td>—</td><td>new: server-error diagnostics</td></tr><tr><td><code>retry</code></td><td>carries <code>error</code></td><td>carries <code>error | response</code></td></tr><tr><td><code>before-request</code>, <code>after-request</code></td><td>per attempt (<code>executor.ts:567</code>, <code>:605</code>)</td><td>unchanged, per attempt</td></tr></tbody></table><p>Event trees per scenario (<code>before-request</code>/<code>after-request</code>/<code>error</code> all fire per attempt today — grounded at <code>executor.ts:567,605,536</code>):</p><pre><code>\`\`\`
200 success (identical both versions)      400 Bad Request
├─ before-request                          TODAY                 NEW
├─ after-request                           ├─ before-request     ├─ before-request
└─ response                                ├─ after-request      ├─ after-request
                                           └─ error              ├─ response
                                                                 └─ response-4xx
                                                                 ⇒ resolves { ok: false }

500 with retry (maxAttempts 3)             Dropped connection (both versions)
TODAY (per attempt)   NEW (per attempt)    attempt N
├─ before-request     ├─ before-request    ├─ before-request
├─ after-request      ├─ after-request     │  ✖ fetch rejects — no after-request
├─ error              ├─ response          ├─ error (step &#39;fetch&#39;)
├─ retry              ├─ response-5xx      ├─ retry (carries FetchError)
...                   ├─ retry (response)  └─ error — THROWS in both versions
└─ error → THROWS     ...
                      └─ response + response-5xx
                      ⇒ resolves { ok: false, status: 500 }

Parse failure on 200 (both: error, step    Parse failure on 500 + .json():
&#39;parse&#39; — contract broken)                 TODAY: error (masks the 500)
                                           NEW: response + response-5xx,
                                                data = raw text
\`\`\`
</code></pre><h2 id="blast-radius" tabindex="-1">Blast radius <a class="header-anchor" href="#blast-radius" aria-label="Permalink to “Blast radius”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Coupling</th><th>Work</th></tr></thead><tbody><tr><td>executor (<code>engine/executor.ts</code>)</td><td>ok-throw at <code>:715-724</code>; <code>#handleError</code> step-response branch <code>:479-508</code>; <code>err.data</code> smuggling</td><td>delete throw + branch; emit new events; build <code>ok</code> discriminant</td></tr><tr><td>retry plugin (<code>plugins/retry.ts:128-158</code>)</td><td>total — throw-driven loop</td><td>second trigger on <code>result.ok === false</code> + <code>retryableStatusCodes</code>; union <code>shouldRetry</code>; <code>retry</code> event payload; default config in <code>helpers/validations.ts</code></td></tr><tr><td>cache plugin (<code>plugins/cache.ts</code>)</td><td>protected by the throw today</td><td><code>ok: false</code> guard in afterRequest store (<code>:461-489</code>) AND in SWR revalidation (<code>:540-576</code> — a resolving 500 would otherwise overwrite good stale data: silent-corruption risk)</td></tr><tr><td>dedupe plugin</td><td>none semantically</td><td>joiners share <code>ok: false</code> responses; no change required</td></tr><tr><td>rate-limit plugin</td><td>none — pre-response phase</td><td>untouched; <code>RateLimitError</code> stays an error</td></tr><tr><td>cookies plugin</td><td>starved by the throw</td><td>gains Set-Cookie capture on non-2xx for free (latent bug fix); needs pinning test</td></tr><tr><td><code>FetchResponse</code> (<code>types.ts</code>)</td><td>—</td><td>discriminated union <code>{ ok: true, data: T } | { ok: false, data: unknown }</code>; ripples through <code>FetchPromise</code> + all method signatures</td></tr><tr><td><code>FetchError</code> (<code>helpers/fetch-error.ts</code>)</td><td>—</td><td>drop <code>data</code> + <code>T</code> generic; <code>step</code> narrows to <code>&#39;fetch&#39; | &#39;parse&#39;</code>; 499 helpers stay</td></tr><tr><td>events (<code>engine/events.ts</code>)</td><td>—</td><td>EventMap additions; <code>retry</code> payload union</td></tr><tr><td>react package</td><td>real design work</td><td>see below</td></tr><tr><td>tests</td><td>33 fetch files (~17.5k lines; 7 assert throw-on-status) + 6 react files</td><td>rewrite error-path assertions; add pinning tests</td></tr><tr><td>docs</td><td>9 surfaces</td><td><code>skills/logosdx/references/fetch.md</code>, <code>docs/packages/fetch/{resilience,configuration,events}.md</code>, <code>docs/wiki/fetch.md</code>, <code>docs/what-is-logosdx.md</code>, <code>docs/packages/react.md</code> (llm copies regenerate)</td></tr></tbody></table><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to “Invariants”">​</a></h2><ul><li>A <code>FetchError</code> exists <strong>iff</strong> no usable response exists. Every completed exchange resolves.</li><li>The body format never masks the status (<code>ok: false</code> parse falls back to text).</li><li><code>ok: false</code> is never cached — neither in the afterRequest store nor via SWR revalidation.</li><li>Set-Cookie is captured regardless of status.</li><li>Diagnostics events fire per attempt; <code>requestId</code> ties attempts together.</li><li>Only the parsed paths change; <code>.raw()</code> / <code>.stream()</code> keep their existing resolve semantics.</li></ul><h2 id="react-hooks-error-state-shape" tabindex="-1">React hooks error-state shape <a class="header-anchor" href="#react-hooks-error-state-shape" aria-label="Permalink to “React hooks error-state shape”">​</a></h2><p>Today <code>useQuery</code> / <code>useMutation</code> / <code>useFetch</code> expose <code>error: FetchError | null</code> and consumers read <code>error.status</code>. With the engine resolving non-2xx, the hooks must choose:</p><table tabindex="0"><thead><tr><th>#</th><th>Shape</th><th>Pros</th><th>Cons</th></tr></thead><tbody><tr><td>R1</td><td>Conflate: <code>error</code> fed by both transport errors and <code>ok: false</code> responses</td><td>Zero-surprise for UI code (&quot;did it fail?&quot; = one check)</td><td>Re-conflates the channels the engine just separated; awkward union type</td></tr><tr><td>R2</td><td>Discriminate: <code>error</code> transport-only; expose <code>response</code>, consumer checks <code>!response.ok</code></td><td>Mirrors engine contract</td><td>Every UI must check two fields; silent breakage for existing &quot;render on error&quot; code</td></tr><tr><td>R3</td><td>Discriminated failure union: <code>failure: { kind: &#39;transport&#39;, error } | { kind: &#39;http&#39;, response } | null</code></td><td>One failure check for UI <strong>and</strong> channels stay distinguishable; honest type</td><td>Field rename (fine in a major)</td></tr></tbody></table><p><strong>Recommendation: R3.</strong> UI code overwhelmingly wants one &quot;it failed&quot; state — the hook layer is the right altitude to re-merge, but the union keeps the distinction available (<code>failure.kind === &#39;http&#39; &amp;&amp; failure.response.status === 404</code>). Pending user veto.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to “Open questions”">​</a></h2><ul><li>React hooks failure shape — R3 recommended, awaiting user confirmation (veto window: design review).</li></ul>`,31))])}const v=d(p,[["render",u]]);export{k as __pageData,v as default};
